int ota_apply_update(const ota_header_t *hdr, const uint8_t *payload) {
    if (!verify_signature(hdr, payload)) {
        return OTA_ERR_SIGNATURE;
    }

    // Get current running firmware version
    esp_app_desc_t running_app_info;
    if (esp_ota_get_partition_description(esp_ota_get_running_partition(), &running_app_info) != ESP_OK) {
        return OTA_ERR_VERSION_CHECK_FAILED;
    }

    // Compare new firmware version with current running version
    // Reject if the new version is not greater than the current version
    if (hdr->version <= running_app_info.version) {
        return OTA_ERR_DOWNGRADE;
    }

    flash_write(OTA_PARTITION, payload, hdr->size);
    set_boot_partition(OTA_PARTITION);
    return OTA_OK;
}
